SELECT route_code, origin_hub_id, destination_hub_id, distance_km, scheduled_duration_min, is_seasonal
FROM aero_horizon_routes
WHERE is_seasonal = 1;

SELECT p.product_name, ib.batch_number, ib.quantity_on_hand, ib.expiry_date
FROM products p
JOIN inventory_batches ib ON p.product_id = ib.product_id;

SELECT room_id, room_number, floor_level, has_balcony, status
FROM accommodations
WHERE status = 'Occupied';

SELECT facility_name, city, state
FROM medical_facilities
WHERE is_active = 1;

SELECT product_id, product_name, category, launch_date, warranty_months, is_legacy
FROM product_lines
WHERE is_legacy = 1;

SELECT subscription_tier, AVG(monthly_mrr) AS avg_monthly_mrr
FROM customer_accounts
GROUP BY subscription_tier;

SELECT full_name, role_title, hire_date
FROM studio_member
WHERE is_active = 1 AND hire_date > '2022-01-01';

SELECT gp.title, sm.full_name
FROM game_project gp
JOIN studio_member sm ON sm.lead_producer_id = gp.project_id;

SELECT generic_name, brand_name, strength, unit_cost
FROM medications
WHERE is_active = 1 AND unit_cost > 0.50;

SELECT supplier_name, COUNT(DISTINCT medication_id) AS distinct_medications, SUM(quantity_received) AS total_units_received
FROM inventory_batches
GROUP BY supplier_id, supplier_name;

SELECT buyer_id, full_name, max_budget, preferred_city
FROM buyers
WHERE preferred_city = 'Springfield' AND max_budget > 300000;

SELECT agent_id, COUNT(*) AS property_count, AVG(list_price) AS avg_list_price
FROM properties
GROUP BY agent_id;

SELECT city, COUNT(*) AS total_viewings, COUNT(DISTINCT buyer_id) AS unique_buyers
FROM viewings
GROUP BY city;

SELECT block_id, block_name, acreage, primary_variety, planting_year
FROM orchard_blocks
WHERE acreage > 20;

SELECT destination_market, COUNT(*) AS shipments, SUM(revenue_usd) AS total_revenue
FROM market_shipments
GROUP BY destination_market;

SELECT f.tail_number, a.airline_name, a.hub_airport_code
FROM fleet f
JOIN airlines a ON f.airline_id = a.airline_id;

SELECT airline_name, status, COUNT(*) AS aircraft_count
FROM fleet
GROUP BY airline_name, status;

SELECT generic_name, brand_name, strength, controlled_substance_schedule
FROM medication_catalog
WHERE controlled_substance_schedule >= 2;

SELECT active_subscriptions.subscription_id, active_subscriptions.current_period_start, active_subscriptions.current_period_end, active_subscriptions.status
FROM active_subscriptions
WHERE active_subscriptions.status = 'Past_Due';

SELECT account_id, company_name, primary_contact_email, billing_country, account_tier, created_at, is_active
FROM customer_accounts
WHERE billing_country = 'United States';

SELECT account_tier, AVG(provisioned_seats) AS avg_provisioned_seats, ROUND(100.0 * SUM(CASE WHEN auto_renew = 1 THEN 1 ELSE 0 END) / COUNT(*), 2) AS auto_renew_percentage
FROM active_subscriptions
GROUP BY account_tier;

SELECT i.item_name, s.category_name, s.storage_type
FROM inventory_stock i
JOIN supply_categories s ON i.category_id = s.category_id;

SELECT outlet_id, COUNT(*) AS member_count
FROM team_members
GROUP BY outlet_id;

SELECT outlet_id, AVG(rating) AS avg_rating
FROM guest_feedback
GROUP BY outlet_id;

SELECT outlet_id, MAX(last_restock_date) AS most_recent_restock_date
FROM inventory_stock
GROUP BY outlet_id;

SELECT tower_id, tower_code, region_id, tower_type, latitude, longitude, installation_date, status
FROM network_towers
WHERE status = 'Active';

SELECT customer_accounts.full_name, subscription_tiers.tier_name, subscription_tiers.monthly_fee
FROM customer_accounts
JOIN subscription_tiers ON customer_accounts.tier_id = subscription_tiers.tier_id;

SELECT session_type, SUM(volume_mb) AS total_volume_mb
FROM usage_events
GROUP BY session_type;

SELECT crew_id, full_name, hire_date
FROM crew_members
WHERE hire_date > '2020-01-01';

SELECT leg_id, flight_number, origin_hub_id, destination_hub_id, scheduled_departure, scheduled_arrival, leg_status
FROM flight_legs
WHERE leg_status = 'DELAYED';

SELECT hub_name, COUNT(crew_id) AS crew_count
FROM crew_members
GROUP BY hub_name;
